files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a3c;
  --text: #e0e0e0;
  --accent: #f0a500;
  --accent-hover: #ffc107;
  --bar-bg: #3a3a4c;
  --bar-fill: #f0a500;
  --focus: #ffd54f;
  --border-radius: 12px;
  --padding: 20px;
  --font-size: 18px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: var(--font-size);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.poll-card {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  padding: var(--padding);
  width: 100%;
  max-width: 600px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.4em;
  text-align: center;
  color: var(--accent);
  line-height: 1.3;
}

.options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.option {
  background: var(--bar-bg);
  border-radius: 8px;
  padding: 12px 16px;
  cursor: pointer;
  border: 2px solid transparent;
  transition: background 0.2s, border-color 0.2s;
  display: flex;
  flex-direction: column;
  gap: 6px;
  text-align: left;
  font: inherit;
  color: inherit;
  width: 100%;
  position: relative;
  overflow: hidden;
}

.option:hover {
  background: #4a4a5c;
}

.option:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.option.selected {
  border-color: var(--accent);
}

.option:active {
  transform: scale(0.98);
}

.option-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  z-index: 1;
}

.vote-count {
  font-size: 0.9em;
  color: var(--text);
  opacity: 0.8;
}

.bar-container {
  height: 12px;
  background: var(--bar-bg);
  border-radius: 6px;
  overflow: hidden;
  z-index: 1;
}

.bar-fill {
  height: 100%;
  background: var(--bar-fill);
  width: 0%;
  border-radius: 6px;
  transition: width 0.4s ease;
}

.reset-btn {
  background: transparent;
  border: 2px solid var(--accent);
  color: var(--accent);
  padding: 12px 24px;
  border-radius: 8px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, color 0.2s, transform 0.1s;
  align-self: center;
  min-width: 160px;
}

.reset-btn:hover {
  background: var(--accent);
  color: var(--bg);
}

.reset-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.reset-btn:active {
  transform: scale(0.96);
}

.status {
  text-align: center;
  font-size: 0.9em;
  min-height: 1.2em;
  color: var(--accent);
}

@media (max-width: 400px) {
  :root {
    --padding: 16px;
    --font-size: 16px;
  }
  h1 {
    font-size: 1.2em;
  }
  .option {
    padding: 10px 12px;
  }
}

const options = [
  { id: 'opt1', label: '8-bit' },
  { id: 'opt2', label: '16-bit' },
  { id: 'opt3', label: '32-bit' },
  { id: 'opt4', label: 'Modern pixel' }
];

let votes = options.map(() => 0);
let userVote = null; // index of selected option, null if none

const container = document.getElementById('options-container');
const resetBtn = document.getElementById('reset-btn');
const statusMsg = document.getElementById('status-message');

function render() {
  const total = votes.reduce((a, b) => a + b, 0);
  container.innerHTML = '';
  options.forEach((opt, i) => {
    const btn = document.createElement('button');
    btn.className = 'option' + (userVote === i ? ' selected' : '');
    btn.type = 'button';
    btn.setAttribute('aria-pressed', userVote === i ? 'true' : 'false');
    btn.setAttribute('aria-label', `${opt.label}, ${votes[i]} votes, ${total ? Math.round((votes[i] / total) * 100) : 0}%`);
    btn.dataset.index = i;
    btn.innerHTML = `
      <span class="option-label">
        <span>${opt.label}</span>
        <span class="vote-count">${votes[i]} vote${votes[i] !== 1 ? 's' : ''}</span>
      </span>
      <div class="bar-container">
        <div class="bar-fill" style="width: ${total ? (votes[i] / total) * 100 : 0}%"></div>
      </div>
    `;
    btn.addEventListener('click', () => handleVote(i));
    container.appendChild(btn);
  });
  statusMsg.textContent = userVote !== null ? `You voted for ${options[userVote].label}.` : '';
}

function handleVote(index) {
  if (userVote === index) return; // already voted for this
  if (userVote !== null) {
    votes[userVote]--;
  }
  votes[index]++;
  userVote = index;
  render();
}

resetBtn.addEventListener('click', () => {
  votes = options.map(() => 0);
  userVote = null;
  render();
  statusMsg.textContent = 'Votes reset.';
  setTimeout(() => { if (statusMsg.textContent === 'Votes reset.') statusMsg.textContent = ''; }, 2000);
});

// Initial render
render();
